SELECT DISTINCT t1.email FROM customers AS t1 JOIN (
    SELECT customer_id FROM events WHERE event_type = 'event' AND customer_id IN (
        SELECT customer_id FROM subscriptions WHERE subscription_id IN (
            SELECT subscription_id FROM orders WHERE status = 'subscribed'
        )
    ) GROUP BY customer_id HAVING COUNT(*) > 2
) AS t2 ON t1.customer_id = t2.customer_id
